/**
 * An instance of a ParseResolver will allow data to be extracted out of a target.
 * For instance, a ParseResolver set up to extract the property firstName out of
 * an Object would run this:
 *
 * myParseResolver.resolve({firstName: 'Brian', lastName: 'Bjork'}) returns 'Brian'
 * myParseResolver.resolve({firstName: 'Scott', lastName: 'Weiss'}) returns 'Scott'
 *
 * A more complicated instance might be set up to grab something like user.firstName out of an object.
 */
export interface ParseResolver<T> {
    resolve: (target: any) => T | undefined;
}
